findings.codeql_raw_query:
/**
 * @name Unverified SSL context flows into HTTPS request
 * @description A context created with ssl._create_unverified_context flows into urllib request, disabling certificate verification.
 * @kind problem
 * @problem.severity warning
 * @id py/virtualenv-unverified-ssl-flow
 * @tags security
 *        external/cwe/cwe-295
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.ApiGraphs

module UnverifiedSSLConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source = API::moduleImport("ssl").getMember("_create_unverified_context").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib").getMember("request").getMember(["urlopen", "Request"]).getACall()
      and sink = call.getArgByName("context")
    )
  }
}

module UnverifiedSSLFlow = DataFlow::Global<UnverifiedSSLConfig>;

from DataFlow::Node source, DataFlow::Node sink
where UnverifiedSSLFlow::flow(source, sink)
select sink, "Unverified SSL context flows into $@.", source, "ssl._create_unverified_context()"
